# File: gui.py (estratto strutturale dell'interfaccia e del controller) import tkinter as tk from tkinter import ttk, messagebox from models import ArticoloMagazzino from engine import MotoreCalcoloEOQ from simulator import SimulatoreTriennale class InterfacciaMagazzino:    """Interfaccia grafica desktop per il calcolo EOQ/ROP e la simulazione triennale."""    def __init__(self, root: tk.Tk, motore: MotoreCalcoloEOQ, dataset_triennale: dict):        self.root = root        self.root.title("DSS Gestione Scorte — Modello EOQ & ROP con Safety Stock")        self.root.geometry("920x680")        self.motore = motore        self.dataset_triennale = dataset_triennale        self.campi_input = {}        self.etichette_output = {}        self.costruisci_layout()    def costruisci_layout(self) -> None:        frame_input = ttk.LabelFrame(self.root, text="1. Parametri dell'Articolo e della Domanda", padding=10)        frame_input.pack(fill="x", padx=12, pady=6)        specifiche = [            ("sku", "Codice Articolo (SKU):", "SKU-001"),            ("D", "Domanda Annua D (unità/anno):", "14600"),            ("S", "Costo di Setup/Ordine S (€):", "120.0"),            ("H", "Costo Mantenimento H (€/unità/anno):", "6.5"),            ("L", "Lead Time Medio L (giorni):", "7.0"),            ("sigma_L", "Dev. Std. Lead Time σ_L (giorni):", "1.5"),            ("sigma_d", "Dev. Std. Domanda Giornaliera σ_d:", "12.0"),            ("csl", "Livello di Servizio Target (0.90-0.99):", "0.95"),        ]        for idx, (chiave, testo, default) in enumerate(specifiche):            r, c = divmod(idx, 2)            ttk.Label(frame_input, text=testo).grid(row=r, column=c*2, sticky="w", padx=6, pady=4)            entry = ttk.Entry(frame_input, width=18)            entry.insert(0, default)            entry.grid(row=r, column=c*2 + 1, sticky="w", padx=6, pady=4)            self.campi_input[chiave] = entry        ttk.Button(            frame_input, text="Calcola EOQ, ROP e Simula Triennio",            command=self.esegui_calcolo_e_confronto        ).grid(row=4, column=0, columnspan=4, pady=8)        frame_out = ttk.LabelFrame(self.root, text="2. Risultati Analitici Ottimali", padding=10)        frame_out.pack(fill="x", padx=12, pady=6)        for idx, nome in enumerate(["EOQ (unità)", "Safety Stock (unità)", "Punto Riordino ROP",                                   "Ordini / Anno", "Costo Gestione Annuo (€)"]):